import java.util.Scanner;

public class Main {
    static final int maxn = 512;
    static long[][] c = new long[maxn][maxn];
    static long[][] p = new long[maxn][maxn];
    static long n, m, M;
    static long me, you;

    static long g(int a, int b) {
        if (b == 0)
            return 1;
        return p[a + 1][b - 1] * p[2][b] % M * (a + 1 - b) % M;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextLong();
        M = sc.nextLong();

        for (int i = 0; i < maxn; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0)
                    c[i][j] = 1;
                else
                    c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % M;
            }
        }

        for (int i = 0; i < maxn; i++) {
            for (int j = 0; j < maxn; j++) {
                if (j == 0)
                    p[i][j] = 1;
                else
                    p[i][j] = p[i][j - 1] * i % M;
            }
        }

        you = 0;
        for (int i = 2; i <= m; i++) {
            for (int d = 1; d < i; d++) {
                me = d * (d + 1) / 2 % M
                        * c[(int) (i - 1)][d] % M
                        * p[d + 1][d - 1] % M
                        * g((int) (n + 1 - (d + 1) - 1), i - (d + 1)) % M
                        * p[2][d] % M
                        * p[(int) (n + 1 - m)][(int) (m - i)] % M
                        * p[2][(int) (m - i)] % M;
                you = (you + me + me) % M;
            }
        }

        System.out.println(you * (n + 1 - m) % M);
        sc.close();
    }
}
